<?php
declare(strict_types=1);namespace Liberu\Accounting\FixedAssetsApi\Http\Resources;use Illuminate\Http\Request;use Illuminate\Http\Resources\Json\JsonResource;use Liberu\Accounting\FixedAssets\Models\Asset;/** @mixin Asset */final class AssetResource extends JsonResource {public function toArray(Request $request):array{$a=$this->resource;return['id'=>$a->getKey(),'asset_ref'=>$a->asset_ref,'name'=>$a->name,'status'=>$a->status->value,'acquired_on'=>$a->acquired_on,'capitalized_on'=>$a->capitalized_on,'cost'=>$a->cost,'salvage_value'=>$a->salvage_value,'net_book_value'=>$a->net_book_value,'currency'=>$a->currency,'location_ref'=>$a->location_ref,'custodian_ref'=>$a->custodian_ref,'category'=>$this->whenLoaded('category'),'books'=>$this->whenLoaded('books'),'components'=>$this->whenLoaded('components'),'documents'=>$this->whenLoaded('documents')];}}
